INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling Squat', 'Fessiers', 'Barre', '1. Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your genoux. Slide under the bar, racking it across the back of your epaules. Your omoplates should be retracted and the bar tight across votre dos. Unrack the poids. 2. With your head looking forward, sit back with your butt until you touch your mollets. 3. Reverse the motion, returning the torse to an upright position.', 'Muscles secondaires : Abdominaux, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Landmine 180''s', 'Abdominaux', 'Barre', '1. Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate poids. 2. Raise the bar from le sol, taking it to epaules height with both hands with vos bras extended in front of you. Adopt a wide stance. Position de depart. 3. Perform le mouvement by rotating the trunk and hips as you swing the poids all the way down to one side. Keep vos bras extended throughout the exercise. 4. Reverse the motion to swing the poids all the way to the opposite side. 5. Continue alternating le mouvement until the set is complete.', 'Muscles secondaires : Fessiers, Bas du dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Landmine_180s/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Landmine Linear Jammer', 'Épaules', 'Barre', '1. Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate poids and position the handle attachment on the bar. 2. Raise the bar from le sol, taking the handles to your epaules. Position de depart. 3. In an athletic stance, squat by flexing your hips and setting your hips back, keeping vos bras flexed. 4. Reverse the motion by powerfully extending through the hips, genoux, and ankles, while also extending the coudes to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible. 5. Revenez en position de depart.', 'Muscles secondaires : Abdominaux, Mollets, Pectoraux, Ischio-jambiers, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Landmine_Linear_Jammer/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lateral Bound', 'Adducteurs', 'Poids de corps', '1. Assume a half squat position facing 90 degrees from your direction of travel. Position de depart. 2. Allow your lead leg to do a countermovement inward as you shift your poids to the outside leg. 3. Immediately push off and extend, attempting to bound to the side as far as possible. 4. Upon landing, immediately push off in the opposite direction, returning to your original start position. 5. Continue back and forth for several repetitions.', 'Muscles secondaires : Abducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Bound/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lateral Box Jump', 'Adducteurs', 'Autre', '1. Assume a comfortable standing position, with a short box positioned next to you. Position de depart. 2. Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side. 3. Bring your genoux high enough to ensure vos pieds have good clearance over the box. 4. Land on the center of the box, using vos jambes to absorb the impact. 5. Carefully jump down to the other side of the box, and continue going back and forth for several repetitions.', 'Muscles secondaires : Abducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Box_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lateral Cone Hops', 'Adducteurs', 'Autre', '1. Position a number of cones in a row several feet apart. 2. Stand next to the end of the cones, facing 90 degrees to the direction of travel. Position de depart. 3. Begin the jump by dipping with the genoux to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone. 4. Use vos jambes to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.', 'Muscles secondaires : Abducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Cone_Hops/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lateral Raise - With Bands', 'Épaules', 'Élastique', '1. To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your cuisses) grip that is slightly less than epaules width. The handles should be resting on the sides of your cuisses. vos bras should be extended with a slight bend at the coudes and votre dos should be straight. Position de depart. 2. Use your side epaules to lift the handles to the sides en expirant. Continue to lift the handles until they are slightly above parallel. Conseil : As you lift the handles, slightly tilt the hand as if you were pouring water and keep vos bras extended. Also, keep your torse stationary and pause for a second at the top of le mouvement. 3. Lower the handles back down Lentement, to the position de depart. Inhale as you perform this portion of le mouvement. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Raise_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Latissimus Dorsi-SMR', 'Dos', 'Foam roller', '1. While lying on le sol, place a foam roll under votre dos and to one side, just behind your arm pit. Position de depart. 2. Keep the arm of the side being stretched behind and to the side of you as you shift your poids onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Latissimus_Dorsi-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg-Over Floor Press', 'Pectoraux', 'Kettlebell', '1. Allongez-vous au sol with one kettlebells in place on your poitrine, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support. 2. Press the kettlebll into a locked out position. 3. Lower the poids until the coudes touches the ground, keeping the kettlebells above the coudes. Repetez for the desired number of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg-Over_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg-Up Hamstring Stretch', 'Ischio-jambiers', 'Autre', '1. Allongez-vous au sol, bend one genoux, and put that foot flat on le sol to stabilize your spine. 2. Extend the other leg in the air. If you''re tight, you wont be able to straighten it. That''s okay. Extend the genoux so that the sole of the lifted foot faces the ceiling (or as close as you can get it). 3. Lentement, straighten the legs as much as possible and then pull the leg toward your nose. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg-Up_Hamstring_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg Extensions', 'Quadriceps', 'Machine', '1. For this exercise you will need to use a leg extension machine. First choose your poids and sit on the machine with vos jambes under the pad (feet pointed forward) and the hands holding the side bars. Position de depart. Conseil : You will need to adjust the pad so that it falls on top of your lower leg (just above vos pieds). Also, make sure that vos jambes form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the genoux is over the toes which in turn creates undue stress at the genoux joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle. 2. Using your quadriceps, extend vos jambes to the maximum en expirant. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position. 3. Lentement, lower the poids back to the original position en inspirant, ensuring that you do not go past the 90-degree angle limit. 4. Repetez for the recommended amount of times.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg Lift', 'Fessiers', 'Poids de corps', '1. While standing up straight with both feet next to each other at around epaules width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance. 2. With or without an ankle poids, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Expirez as you perform this movement. 3. Lentement, bring the raised leg back to le sol as you Inspirez. 4. Repetez selon le nombre souhaite. 5. Repetez le mouvement with the opposite leg.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Lift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg Press', 'Quadriceps', 'Machine', '1. Using a leg press machine, sit down on the machine and place vos jambes on the platform directly in front of you at a medium (epaules width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section). 2. Lower the safety bars holding the weighted platform in place and press the platform all the way up until vos jambes are fully extended in front of you. Conseil : Make sure that you do not lock your genoux. Your torse and the legs should make a perfect 90-degree angle. Position de depart. 3. en inspirant, Lentement, lower the platform until your upper and lower legs make a 90-degree angle. 4. Pushing mainly with the heels of vos pieds and using the quadriceps go back to the position de depart en expirant. 5. Repetez selon le nombre souhaite. and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg Pull-In', 'Abdominaux', 'Poids de corps', '1. Lie on an exercise mat with vos jambes extended and vos mains either palms facing down next to you or under your fessiers. Conseil : My preference is with the hands next to me. Position de depart. 2. Bend your genoux and pull your upper cuisses into your midsection as you Expirez. Continue the motion until your genoux are around poitrine level. Contract your abdominaux as you execute this movement and Maintenez 1 seconde at the top. Conseil : As you perform the motion, the lower legs (mollets) should always remain parallel to le sol. 3. Revenez en position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Pull-In/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Chest Press', 'Pectoraux', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion. 2. Your poitrine and head should be up and your omoplates retracted. Position de depart. 3. Press the handles forward by extending through the coudes. 4. Apres une pause, at the top, return the poids just above the start position, keeping tension on the muscles by not returning the poids to the stops until the set is complete.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Deadlift', 'Quadriceps', 'Machine', '1. Load the pins to an appropriate poids. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your poitrine up. Position de depart. 2. Return the poids to the position de depart.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Decline Chest Press', 'Pectoraux', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your poitrine and head should be up and your omoplates retracted. Position de depart. 2. Press the handles forward by extending through the coudes. 3. Apres une pause, at the top, return the poids just above the start position, keeping tension on the muscles by not returning the poids to the stops until the set is complete.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Decline_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage High Row', 'Milieu du dos', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the genoux pad to help keep you down. Grasp the handles with a pronated grip. Position de depart. 2. Pull the handles towards your torse, retracting your omoplates as you flex the coudes. 3. Pause at the bottom of the motion, and then Lentement, return the handles to the position de depart. 4. For multiple repetitions, avoid completely returning the poids to the stops to keep tension on the muscles being worked.', 'Muscles secondaires : Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_High_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Incline Chest Press', 'Pectoraux', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your poitrine and head should be up and your omoplates retracted. Position de depart. 2. Press the handles forward by extending through the coudes. 3. Apres une pause, at the top, return the poids just above the start position, keeping tension on the muscles by not returning the poids to the stops until the set is complete.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Incline_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Iso Row', 'Dos', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat height so that the handles are at poitrine level. Grasp the handles with either a neutral or pronated grip. Position de depart. 2. Pull the handles towards your torse, retracting your omoplates as you flex the coudes. 3. Pause at the bottom of the motion, and then Lentement, return the handles to the position de depart. For multiple repetitions, avoid completely returning the poids to the stops to keep tension on the muscles being worked.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Iso_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Shoulder Press', 'Épaules', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat for your height. The handles should be near the top of the epaules at the beginning of the motion. Your poitrine and head should be up and handles held with a pronated grip. Position de depart. 2. Press the handles upward by extending through the coudes. 3. Apres une pause, at the top, return the poids to just above the start position, keeping tension on the muscles by not returning the poids to the stops until the set is complete.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Shrug', 'Trapèzes', 'Machine', '1. Load the pins to an appropriate poids. Position yourself directly between the handles. 2. Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your poitrine up. 3. Drive through le sol with your heels, extending your hips and genoux as you rise to a standing position. Keep vos bras straight throughout le mouvement, finishing with your epaules back. Position de depart. 4. Raise the poids by shrugging the epaules towards your ears, moving straight up and down. 5. Pause at the top of the motion, and then return the poids to the position de depart.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Linear 3-Part Start Technique', 'Ischio-jambiers', 'Autre', '1. This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left. 2. Place your right hand onto the line, and thing bring your nose close to your left genoux. 3. Squat down as you lean foward, your head being lower than your hips and your poids loaded onto the left leg. Position de depart. 4. Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.', 'Muscles secondaires : Mollets, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_3-Part_Start_Technique/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Linear Acceleration Wall Drill', 'Ischio-jambiers', 'Autre', '1. Lean at around 45 degrees against a wall. vos pieds should be together, fessiers contracted. 2. Begin by lifting your right genoux quickly, pausing, and then driving it straight down into the ground. 3. Switch legs, raising the opposite genoux, and then attacking the ground straight down. 4. Repetez once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.', 'Muscles secondaires : Mollets, Fessiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Acceleration_Wall_Drill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Linear Depth Jump', 'Quadriceps', 'Autre', '1. You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform. 2. To initiate le mouvement, gently drop down to the ground between your platforms, allowing the genoux and hips to flex. 3. Reverse the motion by exploding, extending through the hips, genoux, and ankles to jump onto the other platform. 4. Land softly, asborbing the impact through the legs.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Depth_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Log Lift', 'Épaules', 'Autre', '1. Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your poitrine. Extend through the hips and genoux to bring it up to complete the clean. 2. Push your head back and look up, creating a shelf on your poitrine to rest the log. Begin the press by dipping, flexing slightly through the genoux and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the coudes to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward. 3. Repetez as many times as possible. Attempt to control the descent of the log as it is returned to the ground.', 'Muscles secondaires : Abdominaux, Pectoraux, Fessiers, Ischio-jambiers, Bas du dos, Milieu du dos, Quadriceps, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Log_Lift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('London Bridges', 'Dos', 'Autre', '1. Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized. 2. Stand on the bar, using the rope to balance yourself. Position de depart. 3. Keeping votre corps straight, lean back and lower votre corps by Lentement, going hand over hand with the rope. Continue until you are perpendicular to the ground. 4. Keeping votre corps straight, reverse the motion, going hand over hand back to the position de depart.', 'Muscles secondaires : Biceps, Avant-bras, Milieu du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/London_Bridges/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Looking At Ceiling', 'Quadriceps', 'Autre', '1. Kneel on le sol, holding your heels with both hands. 2. Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in votre dos.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Looking_At_Ceiling/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Low Cable Crossover', 'Pectoraux', 'Poulie', '1. To move into the position de depart, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand. 2. Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and vos bras straight. Position de depart. 3. With a slight bend in vos bras, draw vos mains upward and toward the midline of votre corps. vos mains should come together in front of your poitrine, palms facing up. 4. Return vos bras back to the position de depart Apres une pause, .', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Crossover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Low Cable Triceps Extension', 'Triceps', 'Poulie', '1. Select the desired poids and lay down face up on the banc of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment. 2. Grab the outside of the rope ends with your palms facing each other (neutral grip). 3. Position your coudes so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torse. Conseil : Keep the coudes in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. Position de depart. 4. As you Expirez, extend your lower arms until they are straight and vertical. The upper arms and coudes remain stationary throughout le mouvement. Only the forearms should move. Contract the triceps hard for a second. 5. As you Inspirez Lentement, Revenez en position de depart. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Low Pulley Row To Neck', 'Épaules', 'Poulie', '1. Sit on a low pulley row machine with a rope attachment. 2. Grab the ends of the rope using a palms-down grip and sit with votre dos straight and your genoux slightly bent. Conseil : Keep votre dos almost completely vertical and vos bras fully extended in front of you. Position de depart. 3. While keeping your torse stationary, lift your coudes and start bending them as you pull the rope towards your neck while exhaling. Throughout le mouvement your upper arms should remain parallel to le sol. Conseil : Continue this motion until vos mains are almost next to your ears (the forearms will not be parallel to le sol at the end of le mouvement as they will be angled a bit upwards) and your coudes are out away from your sides. 4. After holding for a second or so at the contracted position, come back Lentement, to the position de depart en inspirant. Conseil : Again, during no part of le mouvement should the torse move. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Pulley_Row_To_Neck/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lower Back-SMR', 'Bas du dos', 'Foam roller', '1. In a seated position, place a foam roll under your lower back. Cross vos bras in front of you and protract your epaules. Position de depart. 2. Raise your hips off of le sol and lean back, keeping your poids on your lower back. Now shift your poids slightly to one side, keeping your poids off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repetez de l autre cote.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lower_Back-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lower Back Curl', 'Abdominaux', 'Poids de corps', '1. Lie on your stomach with vos bras out to your sides. Position de depart. 2. Using your lower back muscles, extend your spine lifting your poitrine off of the ground. Do not use vos bras to push yourself up. Keep your head up during le mouvement. Repetez for 10-20 repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lower_Back_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lunge Pass Through', 'Ischio-jambiers', 'Kettlebell', '1. Tenez-vous debout avec your torse upright holding a kettlebells in your right hand. Position de depart. 2. Step forward with your left foot and lower your upper body down by flexing the hip and the genoux, keeping the torse upright. Lower votre dos genoux until it nearly touches the ground. 3. As you lunge, pass the kettlebells under your front leg to your opposite hand. 4. Pressing through the heel of your foot, Revenez en position de depart. 5. Repetez le mouvement for the recommended amount of repetitions, alternating legs.', 'Muscles secondaires : Mollets, Fessiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Pass_Through/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lunge Sprint', 'Quadriceps', 'Machine', '1. Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your epaules. Unrack the bar, and then split vos pieds, moving one foot forward and one foot back. Position de depart. 2. Lower votre dos genoux nearly to the ground, flexing the genoux and lowering your hips as you do so. 3. At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from votre dos foot. Jump up and reverse the position of vos jambes. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Sprint/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Bent Leg Groin', 'Adducteurs', 'Autre', '1. Allongez-vous au sol with your genoux bent and the soles of the feet pressed together. Have your partner hold your genoux. Position de depart. 2. Attempt to squeeze your genoux together, while your partner prevents any movement from occurring. 3. After 10-20 seconds, relax your muscles as your partner gently pushes your genoux towards le sol. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.', 'Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Bent_Leg_Groin/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Cable Curl', 'Biceps', 'Poulie', '1. Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) epaules-width grip. 2. Allongez-vous au sol on top of an exercise mat in front of the poids stack with vos pieds flat against the frame of the pulley machine and vos jambes straight. 3. With vos bras extended and your coudes close to votre corps slightly bend vos bras. Position de depart. 4. While keeping your upper arms stationary and the coudes close to votre corps, curl the bar up Lentement, toward your poitrine as you Expirez and you squeeze the biceps. 5. After a second squeeze at the top of le mouvement, Lentement, Revenez en position de depart. 6. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cable_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Cambered Barbell Row', 'Milieu du dos', 'Barre', '1. Place a cambered bar underneath an exercise banc. 2. Lie face down on the exercise banc and grab the bar using a palms down (pronated grip) that is wider than epaules width. Position de depart. 3. en expirant row the bar up as you keep the coudes close to votre corps to either your poitrine, in order to target the upper mid back, or to your stomach if targeting the lats is your goal. 4. After a second hold at the top, lower back down to the position de depart Lentement, en inspirant.', 'Muscles secondaires : Biceps, Dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cambered_Barbell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Close-Grip Bar Curl On High Pulley', 'Biceps', 'Poulie', '1. Place a flat banc in front of a high pulley or lat pulldown machine. 2. Hold the straight bar attachment using an prise en supination (palms up) that is about epaules width. 3. Allongez-vous au sol with your head over the end of the banc. 4. Now extend vos bras straight above your epaules. Your torse and vos bras should make a 90-degree angle and the coudes should be in. Position de depart. 5. As you Expirez, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Conseil : As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout le mouvement. 6. Revenez en position de depart slowly. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Close-Grip Barbell Triceps Extension Behind The Head', 'Triceps', 'Barre', '1. While holding a barre or EZ Curl bar with a pronated grip (palms facing forward), Allongez-vous au sol on a flat banc with your head close to the end of the banc. Conseil : If you are holding a barre grab it using a epaules-width grip and if you are using an E-Z Bar grab it on the inner handles. 2. Extend vos bras in front of you and Lentement, bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step vos bras should be overhead and parallel to le sol. Position de depart. Conseil : Keep your coudes in en permanence. 3. en inspirant, lower the bar by bending at the coudes and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to le sol. 4. en expirant bring the bar back up to the position de depart by pushing the bar up in a semi-circular motion until the lower arms are also parallel to le sol. Contract the triceps hard at the top of le mouvement for a second. Conseil : Again, only the forearms should move. The upper arms should remain stationary en permanence. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Close-Grip Barbell Triceps Press To Chin', 'Triceps', 'Barre EZ', '1. While holding a barre or EZ Curl bar with a pronated grip (palms facing forward), Allongez-vous au sol on a flat banc with your head off the end of the banc. Conseil : If you are holding a barre grab it using a epaules-width grip and if you are using an E-Z Bar grab it on the inner handles. 2. Extend vos bras in front of you as you hold the barre over your poitrine. The arms should be perpendicular to your torse (90-degree angle). Position de depart. 3. en inspirant, lower the bar in a semi-circular motion by bending at the coudes and while keeping the upper arm stationary and coudes in. Keep lowering the bar until it lightly touches your chin. 4. en expirant bring the bar back up to the position de depart by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of le mouvement for a second. Conseil : Again, only the forearms should move. The upper arms should remain stationary en permanence. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Crossover', 'Abducteurs', 'Poids de corps', '1. Allongez-vous au sol with vos jambes extended. 2. Cross one leg over votre corps with the genoux bent, attempting to touch the genoux to the ground. Your partner should kneel beside you, holding your epaules down with one hand and controlling the crossed leg with the other. Position de depart. 3. Attempt to raise the bent genoux off of the ground as your partner prevents any actual movement. 4. After 10-20 seconds, relax the leg as your partner gently presses the genoux towards le sol. Repetez with the other side.', 'Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Crossover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Dumbbell Tricep Extension', 'Triceps', 'Haltères', '1. Allongez-vous sur un banc plat while holding two halteres directly in front of you. vos bras should be fully extended at a 90-degree angle from your torse and le sol. The palms should be facing in and the coudes should be tucked in. Position de depart. 2. As you Inspirez and you keep the upper arms stationary with the coudes in, Lentement, lower the poids until the halteres are near your ears. 3. At that point, while keeping the coudes in and the upper arms stationary, use the triceps to bring the poids back up to the position de depart as you Expirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Dumbbell_Tricep_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Face Down Plate Neck Resistance', 'Cou', 'Autre', '1. Lie face down with your whole body straight on a flat banc while holding a poids plate behind your head. Conseil : You will need to position yourself so that your epaules are slightly above the end of a flat banc in order for the upper poitrine, neck and face to be off the banc. Position de depart. 2. While keeping the plate secure on the back of your head Lentement, lower your head (as in saying "yes") as you Inspirez. 3. Raise your head back up to the position de depart in a semi-circular motion as you Expirez. Hold the contraction for a second. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Face_Down_Plate_Neck_Resistance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Face Up Plate Neck Resistance', 'Cou', 'Autre', '1. Lie face up with your whole body straight on a flat banc while holding a poids plate on top of your forehead. Conseil : You will need to position yourself so that your epaules are slightly above the end of a flat banc in order for the traps, neck and head to be off the banc. Position de depart. 2. While keeping the plate secure on your forehead Lentement, lower your head back in a semi-circular motion as you Inspirez. 3. Raise your head back up to the position de depart in a semi-circular motion as you Expirez. Hold the contraction for a second. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Face_Up_Plate_Neck_Resistance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Glute', 'Fessiers', 'Poids de corps', '1. Allongez-vous au sol with your partner kneeling beside you. 2. Flex the hip of one leg, raising it off of le sol. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to votre corps. Your partner should hold the genoux and ankle in place. Position de depart. 3. Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg. 4. After 10-20 seconds, completely relax as your partner gently pushes the ankle and genoux towards your poitrine. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.', 'Muscles secondaires : Abducteurs. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Glute/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Hamstring', 'Ischio-jambiers', 'Autre', '1. Allongez-vous au sol with vos jambes extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their epaules to brace your leg if necessary. Position de depart. 2. With your partner holding your leg in place, attempt to flex the genoux, contracting the ischio-jambiers for 10-20 seconds. 3. Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete.', 'Muscles secondaires : Mollets. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Hamstring/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying High Bench Barbell Curl', 'Biceps', 'Barre', '1. Lie face forward on a tall flat banc while holding a barre with a supinated grip (palms facing up). Conseil : If you are holding a barre grab it using a epaules-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper poitrine is over the end of the banc and the barre is hanging in front of you with the arms extended and perpendicular to le sol. Position de depart. 2. While keeping the coudes in and the upper arms stationary, curl the poids up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of le mouvement for a second. 3. en inspirant, Lentement, go back to the position de depart. Conseil : Maintain full control of the poids en permanence and avoid any swinging. Remember, only the forearms should move throughout le mouvement. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_High_Bench_Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Leg Curls', 'Ischio-jambiers', 'Machine', '1. Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of vos jambes (just a few inches under the mollets). Conseil : Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for ischio-jambiers recruitment. 2. Keeping the torse flat on the banc, ensure vos jambes are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). Position de depart. 3. en expirant, curl vos jambes up as far as possible without lifting the upper legs from the pad. Once you hit the entierement contracte position, hold it for a second. 4. en inspirant, bring the legs back to the initial position. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Machine Squat', 'Quadriceps', 'Machine', '1. Adjust the leg machine to a height that will allow you to get inside it with your genoux bent and the cuisses slightly below parallel. 2. Once you select the poids, position yourself inside the machine face up with the genoux bent and cuisses slightly below parallel to the platform. Make sure that the genoux do not go past the toes. The angle created between the ischio-jambiers and the mollets should be one that is slightly less than 90 degrees (since your position de depart requires you to start slightly below parallel). votre dos and your head should be resting on the machine while your epaules are pressed under the epaules pads. 3. Place vos mains by the handles and position vos pieds slightly pointing out at a epaules width position. Position de depart. 4. While pressing with the balls of the feet as you Expirez, make your whole body erect as you squeeze the quads. Maintenez 1 seconde. Conseil : Since you are starting below parallel, you can opt to use vos mains to help you up by pressing on your cuisses only on the first repetition. 5. Lentement, squat down en inspirant but instead of going all the way down to the position de depart, just stop once your cuisses are parallel to the platform. The angle between your ischio-jambiers and mollets should be a 90-degree angle. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Machine_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying One-Arm Lateral Raise', 'Épaules', 'Haltères', '1. While holding a halteres in one hand, lay with your poitrine down on a flat banc. The other hand can be used to hold to the leg of the banc for stability. 2. Position the palm of the hand that is holding the halteres in a neutral manner (palms facing your torse) as you keep the arm extended with the coudes slightly bent. Position de depart. 3. Now raise the arm with the halteres to the side until your coudes is at epaules height and your arm is roughly parallel to le sol en expirant. Conseil : Maintain your arm perpendicular to the torse while keeping your arm extended throughout le mouvement. Also, keep the contraction at the top for a second. 4. Lentement, lower the halteres to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_One-Arm_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Prone Quadriceps', 'Quadriceps', 'Poids de corps', '1. Lay face down on le sol with your partner kneeling beside you. Flex one genoux and raise that leg off the ground, attempting to touch your fessiers with your foot. Your partner should hold the genoux and ankle. Position de depart. 2. Attempt to extend your genoux while your partner prevents any actual movement. 3. After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your fessiers, further stretching the quadriceps and hip flexors. 4. After 10-20 seconds, switch sides.', 'Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Prone_Quadriceps/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Rear Delt Raise', 'Épaules', 'Haltères', '1. While holding a halteres in each hand, lay with your poitrine down on a flat banc. 2. Position the palms of the hands in a neutral manner (palms facing your torse) as you keep the arms extended with the coudes slightly bent. Position de depart. 3. Now raise the arms to the side until your coudes are at epaules height and vos bras are roughly parallel to le sol en expirant. Conseil : Maintain vos bras perpendicular to the torse while keeping them extended throughout le mouvement. Also, keep the contraction at the top for a second. 4. Lentement, lower the halteres to the position de depart en inspirant. 5. Repetez selon le nombre souhaite. and then switch to the other arm.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Rear_Delt_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Supine Dumbbell Curl', 'Biceps', 'Haltères', '1. Allongez-vous sur un banc plat face up while holding a halteres in each arm on top of your cuisses. 2. Bring the halteres to the sides with the arms extended and the palms of the hands facing your cuisses (neutral grip). 3. While keeping the arms close to your torse and coudes in, Lentement, lower vos bras (as you keep them extended with a slight bend at the coudes) as far down towards le sol as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your position de depart. 4. As you Expirez, Lentement, begin to curl the poids up as you simultaneously rotate your poignets so that the palms of the hands face up. Continue curling the poids until your biceps are entierement contracte and squeeze hard at the top position for a second. Conseil : Only the forearms should move. Upper arms should remain stationary and coudes should stay in throughout le mouvement. 5. Return back to the position de depart very slowly.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Supine_Dumbbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying T-Bar Row', 'Milieu du dos', 'Machine', '1. Load up the T-bar Row Machine with the desired poids and adjust the leg height so that your upper poitrine is at the top of the pad. Conseil : In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper poitrine at the top of the pad. 2. Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of votre dos you want to emphasize. 3. Lift the bar off the rack and extend vos bras in front of you. Position de depart. 4. en expirant Lentement, pull the poids up and squeeze votre dos at the top of le mouvement. Conseil : Keep the upper arms as close to the torse as possible throughout le mouvement in order to better engage the back muscles. Also, do not lift votre corps off of the pad at any time and refrain from using the biceps to lift the poids. 5. After a second contraction at the top of le mouvement, en inspirant, Lentement, go back down to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_T-Bar_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Triceps Press', 'Triceps', 'Barre EZ', '1. Allongez-vous sur un banc plat with either an e-z bar (my preference) or a straight bar placed on le sol behind your head and vos pieds on le sol. 2. Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you bras tendus. Conseil : The arms should be perpendicular to the torse and le sol. The coudes should be tucked in. Position de depart. 3. As you Inspirez, Lentement, lower the poids until the bar lightly touches your forehead while keeping the upper arms and coudes stationary. 4. At that point, use the triceps to bring the poids back up to the position de depart as you Expirez. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Triceps_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Bench Press', 'Pectoraux', 'Machine', '1. Sit down on the poitrine Press Machine and select the poids. 2. Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms. 3. Grab the handles with a palms-down grip and lift your coudes so that your upper arms are parallel to le sol to the sides of your torse. Conseil : Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the position de depart. 4. Now bring the handles back towards you as you Inspirez. 5. Push the handles away from you as you flex your pecs and you Expirez. Hold the contraction for a second before going back to the position de depart. 6. Repetez for the recommended amount of reps. 7. When finished step on the lever again and Lentement, get the handles back to their original place.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Bicep Curl', 'Biceps', 'Machine', '1. Adjust the seat to the appropriate height and make your poids selection. Place your upper arms against the pads and grasp the handles. Position de depart. 2. Perform le mouvement by flexing the coudes, pulling your lower arm towards your upper arm. 3. Pause at the top of le mouvement, and then Lentement, return the poids to the position de depart. 4. Avoid returning the poids all the way to the stops until the set is complete to keep tension on the muscles being worked.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Bicep_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Preacher Curls', 'Biceps', 'Machine', '1. Sit down on the Preacher Curl Machine and select the poids. 2. Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an prise en supination (palms facing up). Conseil : Make sure that when you place the arms on the pad you keep the coudes in. Position de depart. 3. Now lift the handles en expirant and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Conseil : Only the forearms should move. The upper arms should remain stationary and on the pad en permanence. 4. Lower the handles Lentement, back to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Preacher_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Shoulder (Military) Press', 'Épaules', 'Machine', '1. Sit down on the epaules Press Machine and select the poids. 2. Grab the handles to your sides as you keep the coudes bent and in line with your torse. Position de depart. 3. Now lift the handles en expirant and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second. 4. Lower the handles Lentement, back to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Shoulder_Military_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Triceps Extension', 'Triceps', 'Machine', '1. Adjust the seat to the appropriate height and make your poids selection. Place your upper arms against the pads and grasp the handles. Position de depart. 2. Perform le mouvement by extending the coudes, pulling your lower arm away from your upper arm. 3. Pause at the completion of le mouvement, and then Lentement, return the poids to the position de depart. 4. Avoid returning the poids all the way to the stops until the set is complete to keep tension on the muscles being worked.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Medicine Ball Chest Pass', 'Pectoraux', 'Medecine ball', '1. You will need a partner for this exercise. Lacking one, this movement can be performed against a wall. 2. Begin facing your partner holding the medicine ball at your torse with both hands. 3. Pull the ball to your poitrine, and reverse the motion by extending through the coudes. For sports applications, you can take a step as you throw. 4. Your partner should catch the ball, and throw it back to you. 5. Receive the throw with both hands at poitrine height.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Chest_Pass/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Medicine Ball Full Twist', 'Abdominaux', 'Medecine ball', '1. For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. Position de depart. 2. Hold the ball in front of the trunk. Open the hips and turn the epaules at the same time as your partner. 3. For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise. 4. Pass the ball to your partner, and both of you can now twist in the opposite direction to Repetez the procedure.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Full_Twist/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Medicine Ball Scoop Throw', 'Épaules', 'Medecine ball', '1. Assume a semisquat stance with a medicine ball in vos mains. vos bras should hang so the ball is near vos pieds. 2. Begin by thrusting the hips forward as you extend through the legs, jumping up. 3. As you do, swing vos bras up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you.', 'Muscles secondaires : Abdominaux, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Scoop_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Middle Back Shrug', 'Milieu du dos', 'Haltères', '1. Lie facedown on an incline banc while holding a halteres in each hand. vos bras should be fully extended hanging down and pointing towards le sol. The palms of vos mains should be facing each other. Position de depart. 2. en expirant, squeeze your omoplates together and hold the contraction for a full second. Conseil : This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms. 3. en inspirant go back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Middle_Back_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Middle Back Stretch', 'Milieu du dos', 'Autre', '1. Stand so vos pieds are epaules width apart and vos mains are on your hips. 2. Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side.', 'Muscles secondaires : Abdominaux, Dos, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Middle_Back_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Mixed Grip Chin', 'Milieu du dos', 'Autre', '1. Using a spacing that is just about 1 inch wider than epaules width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. Position de depart. 2. Now start to pull yourself up en expirant. Conseil : With the arm that has the palms facing up concentrate on using the back muscles in order to perform le mouvement. The coudes of that arm should remain close to the torse. With the other arm that has the palms facing forward, the coudes will be away but in line with the torse. You will concentrate on using the lats to pull votre corps up. 3. After a second contraction at the top, start to Lentement, come down en inspirant. 4. Repetez selon le nombre souhaite. 5. On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left.', 'Muscles secondaires : Biceps, Dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mixed_Grip_Chin/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Monster Walk', 'Abducteurs', 'Élastique', '1. Place a band around both ankles and another around both genoux. There should be enough tension that they are tight when vos pieds are epaules width apart. 2. To begin, take short steps forward alternating your left and right foot. 3. After several steps, do just the opposite and walk backward to where you started.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Monster_Walk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Mountain Climbers', 'Quadriceps', 'Autre', '1. Begin in a pushup position, with your poids supported by vos mains and toes. Flexing the genoux and hip, bring one leg until the genoux is approximately under the hip. Position de depart. 2. Explosively reverse the positions of vos jambes, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and genoux flexed. Repetez in an alternating fashion for 20-30 seconds.', 'Muscles secondaires : Pectoraux, Ischio-jambiers, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mountain_Climbers/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Moving Claw Series', 'Ischio-jambiers', 'Autre', '1. This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the genoux, aiming to kick your fessiers as the hip extends. 2. Reload the quad as the leg moves back forward, attacking the ground on the next step. 3. Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.', 'Muscles secondaires : Mollets, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Moving_Claw_Series/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Muscle Snatch', 'Ischio-jambiers', 'Barre', '1. Begin with a loaded barre held at the mid cuisses position with a prise large. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the poitrine up and the head looking forward. The epaules should be just in front of the bar. This will be the position de depart. 2. Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips genoux and ankles, driving the bar up as quickly as possible. The bar should be close to the body. 3. Continue raising the bar to the overhead position, without rebending the genoux.', 'Muscles secondaires : Fessiers, Bas du dos, Quadriceps, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Muscle_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Muscle Up', 'Dos', 'Autre', '1. Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the coudes down to your side, flexing the coudes. 2. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your epaules forward, allowing your coudes to move straight back behind you. This puts you into the proper position to continue into the dip portion of le mouvement. 3. Maintaining control and stability, extend through the coudes to complete the motion. 4. Use care when lowering yourself to the ground.', 'Muscles secondaires : Abdominaux, Biceps, Avant-bras, Milieu du dos, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Muscle_Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Narrow Stance Hack Squats', 'Quadriceps', 'Machine', '1. Place the back of your torse against the back pad of the machine and hook your epaules under the epaules pads provided. 2. Position vos jambes in the platform using a less than epaules width narrow stance with the toes slightly pointed out. vos pieds should be around 3 inches or less apart. Conseil : Keep your head up en permanence and also maintain the back on the pad en permanence. 3. Place vos bras on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position). 4. Now straighten vos jambes without locking the genoux. Position de depart. 5. Begin to Lentement, lower the unit by bending the genoux as you maintain a straight posture with the head up (back on the pad en permanence). Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. 6. Begin to raise the unit en expirant by pushing le sol with mainly with the heels of vos pieds as you straighten the legs again and go back to the position de depart. 7. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Hack_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Narrow Stance Leg Press', 'Quadriceps', 'Machine', '1. Using a leg press machine, sit down on the machine and place vos jambes on the platform directly in front of you at a less-than-epaules-width narrow stance with the toes slightly pointed out. vos pieds should be around 3 inches or less apart. Conseil : Keep your head up en permanence and also maintain the back on the pad en permanence. 2. Lower the safety bars holding the weighted platform in place and press the platform all the way up until vos jambes are fully extended in front of you. Conseil : Make sure that you do not lock your genoux. Your torse and the legs should make a perfect 90-degree angle. Position de depart. 3. en inspirant, Lentement, lower the platform until your upper and lower legs make a 90-degree angle. 4. Pushing mainly with the heels of vos pieds and using the quadriceps go back to the position de depart en expirant. 5. Repetez selon le nombre souhaite. and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Leg_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Narrow Stance Squats', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a less-than-epaules-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up en permanence (looking down will get you off balance) and maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section). 4. Begin to Lentement, lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol with the heel of your foot mainly as you straighten the legs again and go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Natural Glute Ham Raise', 'Ischio-jambiers', 'Poids de corps', '1. Using the leg pad of a lat pulldown machine or a preacher banc, position yourself so that your ankles are under the pads, genoux on the seat, and you are facing away from the machine. You should be upright and maintaining good posture. 2. Position de depart. Lower yourself under control until your genoux are almost completely straight. 3. Remaining in control, raise yourself back up to the position de depart. 4. If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.', 'Muscles secondaires : Mollets, Fessiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Natural_Glute_Ham_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Neck-SMR', 'Cou', 'Autre', '1. Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. Position de depart. 2. Starting at the top of your neck, Lentement, roll down the muscles of your neck, pausing at points of tension for 10-30 seconds.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Neck-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Neck Press', 'Pectoraux', 'Barre', '1. Allongez-vous au sol on a flat banc. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with vos bras locked. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your neck. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up). 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Neck_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Oblique Crunches', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against le sol. 2. Make sure vos pieds are elevated and resting on a flat surface. 3. Now lift the epaules in which your hand is touching your head. 4. Simply elevate your epaules and body upward until you touch your genoux. For example, if you have your right hand besides your head, then you want to elevate votre corps upwards until your right coudes touches your left genoux. The same variation can be applied doing the inverse and using your left coudes to touch your right genoux. 5. After your genoux touches your coudes, lower votre corps until you have reached the position de depart. 6. Remember to Inspirez during the eccentric (lowering) part of the exercise and to Expirez during the concentric (upward) part of the exercise. 7. Continue alternating in this manner until all of the recommended repetitions for each side have been completed.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Oblique_Crunches/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Oblique Crunches - On The Floor', 'Abdominaux', 'Poids de corps', '1. Start out by lying on your right side with vos jambes lying on top of each other. Make sure your genoux are bent a little bit. 2. Place your left hand behind your head. 3. Once you are in this set position, begin by moving your left coudes up as you would perform a normal crunch except this time the main emphasis is on your obliques. 4. Crunch as high as you can, hold the contraction for a second and then Lentement, drop back down into the position de depart. 5. Remember to Inspirez during the eccentric (lowering) part of the exercise and to Expirez during the concentric (elevation) part of the exercise.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Oblique_Crunches_-_On_The_Floor/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Olympic Squat', 'Quadriceps', 'Barre', '1. Begin with a barre supported on top of the traps. The poitrine should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed. 2. Descend by flexing the genoux, refraining from moving the hips back as much as possible. This requires that the genoux travel forward; ensure that they stay aligned with the feet. The goal is to keep the torse as upright as possible. Continue all the way down, keeping the poids on the front of the heel. 3. At the moment the upper legs contact the lower, reverse the motion, driving the poids upward.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Olympic_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('On-Your-Back Quad Stretch', 'Quadriceps', 'Autre', '1. Allongez-vous sur un banc plat or step, and hang one leg and arm over the side. 2. Bend the genoux and hold the top of the foot. As you do this, be careful not to arch your lower back. 3. Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling. 4. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On-Your-Back_Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('On Your Side Quad Stretch', 'Quadriceps', 'Autre', '1. Start off by lying on your right side, with your right genoux bent at a 90-degree angle resting on le sol in front of you (this stabilizes the torse). 2. Bend your left genoux behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On_Your_Side_Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Dumbbell Row', 'Milieu du dos', 'Haltères', '1. Choose a flat banc and place a halteres on each side of it. 2. Place the right leg on top of the end of the banc, bend your torse forward from the waist until your upper body is parallel to le sol, and place your right hand on the other end of the banc for support. 3. Use the left hand to pick up the halteres on le sol and hold the poids while keeping your lower back straight. The palm of the hand should be facing your torse. Position de depart. 4. Pull the resistance straight up to the side of your poitrine, keeping your upper arm close to your side and keeping the torse stationary. Expirez as you perform this step. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torse should remain stationary and only the arms should move. The forearms should do no other work except for holding the halteres; therefore do not try to pull the halteres up using the forearms. 5. Lower the resistance straight down to the position de depart. Inspirez as you perform this step. 6. Repetez le mouvement for the specified amount of repetitions. 7. Switch sides and Repetez again with the other arm.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Flat Bench Dumbbell Flye', 'Pectoraux', 'Haltères', '1. Allongez-vous sur un banc plat with a halteres in one hand resting on top of your cuisses. The palm of your hand with the halteres in it should be at a neutral grip. 2. By using your cuisses to help you get the halteres up, clean the halteres so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat banc for better support. Position de depart. 3. Your arm with the poids should have a slight bend on your coudes in order to prevent stress at the biceps tendon. Begin by lowering your arm with the poids in it out in a wide arc until you feel a stretch on your poitrine. Inspirez as you perform this portion of le mouvement. Conseil : Keep in mind that throughout le mouvement, your lifting arm should remain stationary; le mouvement should only occur at the epaules joint. 4. Return your lifting arm back to the position de depart as you squeeze your poitrine muscles and Expirez. Conseil : Make sure to use the same arc of motion used to lower the poids. 5. Maintenez 1 seconde at the contracted position and Repetez le mouvement for the prescribed amount of repetitions. 6. Switch arms and Repetez the exercise.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm High-Pulley Cable Side Bends', 'Abdominaux', 'Poulie', '1. Connect a standard handle to a tower. Move cable to highest pulley position. 2. Tenez-vous debout avec side to cable. With one hand, reach up and grab handle with prise en supination. 3. Pull down cable until coudes touches your side and the handle is by your epaules. 4. Position feet hip-width apart. Place free hand on hip to help gauge pivot point. 5. Keep arm in static position. Contract oblique to bring the poids down in a side crunch. 6. Once you reach maximum contraction, Lentement, release the poids to the position de depart. The poids stack should never be unloaded in a resting position. The aim is constant tension during the set. 7. Repetez to failure. 8. Then, reposition and Repetez the same series of movements on the opposite side.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_High-Pulley_Cable_Side_Bends/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Incline Lateral Raise', 'Épaules', 'Haltères', '1. Lie down sideways on an incline banc press with a halteres in the hand. Make sure the epaules is pressing against the incline banc and the arm is lying across votre corps with the palm around your navel. 2. Hold a halteres in your uppermost arm while keeping it extended in front of you parallel to le sol. Position de depart. 3. While keeping the halteres parallel to le sol en permanence, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Conseil : Exhale as you perform this movement. Hold the halteres in the position and feel the contraction in the epaules for a second. 4. While inhaling lower the poids across votre corps back into the position de depart. 5. Repetez le mouvement for the prescribed amount of repetitions. 6. Switch arms and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Incline_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place a kettlebells between vos pieds. As you bend down to grab the kettlebells, push your butt back and keep your eyes looking forward. 2. Clean the kettlebells to your epaules by extending through the legs and hips as you raise the kettlebells towards your epaules. The poignets should rotate as you do so. 3. Return the poids to the position de depart.', 'Muscles secondaires : Fessiers, Bas du dos, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Clean and Jerk', 'Épaules', 'Kettlebell', '1. Hold a kettlebells by the handle. 2. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. 3. Dip votre corps by bending the genoux, keeping your torse upright. 4. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebells overhead to lockout by extending the arms, using votre corps''s momentum to move the poids. 5. Receive the poids overhead by returning to a squat position underneath the poids. 6. Keeping the poids overhead, return to a standing position. Lower the poids to le sol to perform the next repetition.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Clean_and_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Floor Press', 'Pectoraux', 'Kettlebell', '1. Allongez-vous au sol holding a kettlebells with one hand, with your upper arm supported by le sol. The palm should be facing in. 2. Press the kettlebells straight up toward the ceiling, rotating your poignets. 3. Lower the kettlebells back to the position de depart and Repetez.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Jerk', 'Épaules', 'Kettlebell', '1. Hold a kettlebells by the handle. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. Position de depart. 2. Dip votre corps by bending the genoux, keeping your torse upright. 3. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebells overhead to lockout by extending the arms, using votre corps''s momentum to move the poids. Receive the poids overhead by returning to a squat position underneath the poids. Keeping the poids overhead, return to a standing position. 4. Lower the poids to perform the next repetition.', 'Muscles secondaires : Mollets, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Military Press To The Side', 'Épaules', 'Kettlebell', '1. Clean a kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces inward. Position de depart. 2. Look at the kettlebells and press it up and out until it is locked out overhead. 3. Lower the kettlebells back to your epaules under control and Repetez. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Para Press', 'Épaules', 'Kettlebell', '1. Clean a kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. Position de depart. 2. Hold the kettlebells with the coudes out to the side, and press it up and out until it is locked out overhead. 3. Lower the kettlebells back to your epaules under control and Repetez. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Para_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Push Press', 'Épaules', 'Kettlebell', '1. Hold a kettlebells by the handle. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. Position de depart. 2. Dip votre corps by bending the genoux, keeping your torse upright. 3. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebells overhead to lockout by extending the arms, using votre corps''s momentum to move the poids. Lower the poids to perform the next repetition.', 'Muscles secondaires : Mollets, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Push_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Row', 'Milieu du dos', 'Kettlebell', '1. Place a kettlebells in front of vos pieds. Bend your genoux slightly and then push your butt out as much as possible as you bend over to get in the position de depart. Grab the kettlebells and pull it to your stomach, retracting your omoplates and flexing the coudes. Keep votre dos straight. Lower and Repetez.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Snatch', 'Épaules', 'Kettlebell', '1. Place a kettlebells between vos pieds. Bend your genoux and push your butt back to get in the proper position de depart. 2. Look straight ahead and swing the kettlebells back between vos jambes. 3. Immediately reverse the direction and drive through with your hips and genoux, accelerating the kettlebells upward. As the kettlebells rises to your epaules rotate your hand and punch straight up, using momentum to receive the poids locked out overhead.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Split Jerk', 'Épaules', 'Kettlebell', '1. Hold a kettlebells by the handle. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. Position de depart. 2. Dip votre corps by bending the genoux, keeping your torse upright. 3. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebells overhead to lockout by extending the arms, using votre corps''s momentum to move the poids. 4. Receive the poids overhead by returning to a squat position underneath the poids, positioning one leg in front of you and one leg behind you. 5. Keeping the poids overhead, return to a standing position and bring vos pieds together. Lower the poids to perform the next repetition.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Split Snatch', 'Épaules', 'Kettlebell', '1. Hold a kettlebells in one hand by the handle. 2. Squat towards le sol, and then reverse the motion, extending the hips, genoux, and finally the ankles, to raise the kettlebells overhead. 3. After fully extending the body, descend into a lunge position to receive the poids overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion. 4. Return to a standing position, holding the poids overhead, and bring the feet together. Lower the poids to Revenez en position de depart.', 'Muscles secondaires : Ischio-jambiers, Quadriceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Swings', 'Ischio-jambiers', 'Kettlebell', '', 'Muscles secondaires : Mollets, Fessiers, Bas du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Swings/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Long Bar Row', 'Milieu du dos', 'Barre', '1. Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate poids onto your end. 2. Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position. 3. Assume a bent-genoux stance with your hips back and your poitrine up. Your arm should be extended. Position de depart. 4. Pull the poids to your side by retracting the epaules and flexing the coudes. Do not jerk the poids or cheat during le mouvement. 5. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Biceps, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Long_Bar_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Medicine Ball Slam', 'Abdominaux', 'Medecine ball', '1. Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as votre dos leg. Position de depart. 2. Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, genoux, and ankles to load up for the slam. 3. At peak extension, flex the epaules, spine, and hips to throw the ball hard into the ground directly in front of you. 4. Catch the ball on the bounce and continue for the desired number of repetitions.', 'Muscles secondaires : Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Medicine_Ball_Slam/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Open Palm Kettlebell Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place one kettlebells between vos pieds. 2. Grab the handle with one hand and raise the kettlebells rapidly, let it flip so that the ball of the kettlebells lands in the palm of your hand. 3. Throw the kettlebells out in front of you and catch the handle with one hand. 4. Take the kettlebells to le sol and Repetez. Make sure to work both arms.', 'Muscles secondaires : Avant-bras, Fessiers, Bas du dos, Quadriceps, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Open_Palm_Kettlebell_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Overhead Kettlebell Squats', 'Quadriceps', 'Kettlebell', '1. Clean and press a kettlebells with one arm. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so. Press the poids overhead by extending through the coudes.Position de depart. 2. Looking straight ahead and keeping a kettlebells locked out above you, flex the genoux and hips and lower your torse between vos jambes, keeping your head and poitrine up. 3. Pause at the bottom position for a second before rising back to the top, driving through the heels of vos pieds.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Overhead_Kettlebell_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Side Deadlift', 'Quadriceps', 'Barre', '1. Stand to the side of a barre next to its center. Bend your genoux and lower votre corps until you are able to reach the barre. 2. Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a poignets wrap if you are using a significant amount of poids. Position de depart. 3. Use vos jambes to help lift the barre up while exhaling. vos bras should extend fully as bring the barre up until you are in a standing position. 4. Lentement, bring the barre back down while inhaling. Conseil : Make sure to bend your genoux while lowering the poids to avoid any injury from occurring. 5. Repetez selon le nombre souhaite. 6. Switch arms and Repetez le mouvement.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Side_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Side Laterals', 'Épaules', 'Haltères', '1. Pick a halteres and place it in one of vos mains. Your non lifting hand should be used to grab something steady such as an incline banc press. Lean towards your lifting arm and away from the hand that is gripping the incline banc as this will allow you to keep your balance. 2. Tenez-vous debout avec a straight torse and have the halteres by your side at arm''s length with the palm of the hand facing you. Position de depart. 3. While maintaining the torse stationary (no swinging), lift the halteres to your side with a slight bend on the coudes and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to le sol. Exhale as you execute this movement and pause for a second at the top. 4. Lower the halteres back down Lentement, to the position de depart en inspirant. 5. Repetez selon le nombre souhaite. 6. Switch arms and Repetez the exercise.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Side_Laterals/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Legged Cable Kickback', 'Fessiers', 'Poulie', '1. Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle. 2. Face the poids stack from a distance of about two feet, grasping the steel frame for support. 3. While keeping your genoux and hips bent slightly and your abdominaux tight, contract your fessiers to Lentement, "kick" the working leg back in a semicircular arc as high as it will comfortably go as you Expirez. Conseil : At full extension, squeeze your fessiers for a second in order to achieve a peak contraction. 4. Now Lentement, bring your working leg forward, resisting the pull of the cable until you reach the position de depart. 5. Repetez selon le nombre souhaite. 6. Switch legs and Repetez le mouvement for the other side.', 'Muscles secondaires : Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Legged_Cable_Kickback/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Against Wall', 'Dos', 'Autre', '1. From a standing position, place a bent arm against a wall or doorway. 2. Lentement, lean toward your arm until you feel a stretch in your lats.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Against_Wall/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Chin-Up', 'Milieu du dos', 'Autre', '1. For this exercise, start out by placing a towel around a chin up bar. 2. Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel. 3. Bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart.v 4. Pull your torse up until the bar touches your upper poitrine by drawing the epaules and the upper arms down and back. Exhale as you perform this portion of le mouvement. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar. 5. After a second on the contracted position, start to inhale and Lentement, lower your torse back to the position de depart when vos bras are fully extended and the lats are fully stretched. 6. Repetez this motion for the prescribed amount of repetitions. 7. Switch arms and Repetez le mouvement.', 'Muscles secondaires : Biceps, Avant-bras, Dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Chin-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Dumbbell Bench Press', 'Pectoraux', 'Haltères', '1. Allongez-vous sur un banc plat with a halteres in one hand on top of your cuisses. 2. By using your cuisses to help you get the halteres up, clean the halteres up so that you can hold it in front of you at epaules width. Use the hand you are not lifting with to help position the halteres over you properly. 3. Once at epaules width, rotate your poignets forward so that the palm of your hand is facing away from you. Position de depart. 4. Bring down the poids Lentement, to your side as you Inspirez. Keep full control of the halteres en permanence. Conseil : Use the hand that you are not lifting with to help keep the halteres balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side. 5. As you Expirez, push the halteres up using your pectoral muscles. Lock vos bras in the contracted position, squeeze your poitrine, Maintenez 1 seconde and then start coming down slowly. Conseil : It should take at least twice as long to go down than to come up. 6. Repetez le mouvement for the prescribed amount of repetitions of your training program. 7. Switch arms and Repetez le mouvement.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Dumbbell Preacher Curl', 'Biceps', 'Haltères', '1. Grab a halteres with the right arm and place the upper arm on top of the preacher banc or the incline banc. The halteres should be held at epaules length. Position de depart. 2. As you Inspirez, Lentement, lower the halteres until your upper arm is extended and the biceps is fully stretched. 3. en expirant, use the biceps to curl the poids up until your biceps is entierement contracte and the halteres is at epaules height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb. 4. Squeeze the biceps hard for a second at the contracted position and Repetez selon le nombre souhaite. 5. Switch arms and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Preacher_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Floor Press', 'Triceps', 'Barre', '1. Lie down on a flat surface with votre dos pressing against le sol or an exercise mat. Make sure your genoux are bent. 2. Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the position de depart of a barre banc press. However, this time your grip will be neutral (palms facing your torse). 3. Make sure the hand you are not using to lift the poids is placed by your side. 4. Begin the exercise by lowering the barre until your coudes touches the ground. Make sure to Inspirez as this is the eccentric (lowering part of the exercise). 5. Then start lifting the barre back up to the original position de depart. Remember to Expirez during the concentric (lifting part of the exercise). 6. Repetez until you have performed your recommended repetitions. 7. Switch arms and Repetez le mouvement.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Lat Pulldown', 'Dos', 'Poulie', '1. Select an appropriate poids and adjust the genoux pad to help keep you down. Grasp the handle with a pronated grip. Position de depart. 2. Pull the handle down, squeezing your coudes to your side as you flex the coudes. 3. Pause at the bottom of the motion, and then Lentement, return the handle to the position de depart. 4. For multiple repetitions, avoid completely returning the poids to keep tension on the muscles being worked.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Lat_Pulldown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Pronated Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. Lie flat on a banc while holding a halteres bras tendus. Your arm should be perpendicular to votre corps. The palm of your hand should be facing towards vos pieds as a pronated grip is required to perform this exercise. 2. Place your non lifting hand on your biceps for support. 3. Lentement, begin to lower the halteres down as you Inspirez. 4. Then, begin lifting the halteres upward as you contract the triceps. Remember to Expirez during the concentric (lifting part of the exercise). 5. Repetez until you have performed your set repetitions. 6. Switch arms and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Supinated Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. Lie flat on a banc while holding a halteres bras tendus. Your arm should be perpendicular to votre corps. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise. 2. Place your non lifting hand on your biceps for support. 3. Lentement, begin to lower the halteres down as you Inspirez. 4. Then, begin lifting the halteres upward as you contract the triceps. Remember to Expirez during the concentric (lifting part of the exercise). 5. Repetez until you have performed your set repetitions. 6. Switch arms and Repetez le mouvement. 7. Switch arms again and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Supinated_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Half Locust', 'Quadriceps', 'Autre', '1. Lie facedown on le sol. 2. Put your left hand under your left hipbone to pad your hip and pubic bone. 3. Bend your right genoux so you can hold the foot in your right hand. 4. Lift the foot in the air and simultaneously lift your epaules off le sol. This also stretches the right hip flexor and the poitrine and epaules. Switch sides. If it doesn''t bother votre dos, you can try it with both arms and legs at the same time.', 'Muscles secondaires : Abdominaux, Biceps, Pectoraux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Half_Locust/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Handed Hang', 'Dos', 'Autre', '1. Grab onto a chinup bar with one hand, using a pronated grip. Keep vos pieds on le sol or a step. Allow the majority of your poids to hang from that hand, while keeping vos pieds on the ground. Hold for 10-20 seconds and switch sides.', 'Muscles secondaires : Biceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Handed_Hang/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Knee To Chest', 'Fessiers', 'Autre', '1. Start off by lying on le sol. 2. Extend one leg straight and pull the other genoux to your poitrine. Hold under the genoux joint to protect the kneecap. 3. Gently tug that genoux toward your nose. 4. Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.', 'Muscles secondaires : Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Knee_To_Chest/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Leg Barbell Squat', 'Quadriceps', 'Barre', '1. Start by standing about 2 to 3 feet in front of a flat banc with votre dos facing the banc. Have a barre in front of you on le sol. Conseil : vos pieds should be epaules width apart from each other. 2. Bend the genoux and use a pronated grip with vos mains being wider than epaules width apart from each other to lift the barre up until you can rest it on your poitrine. 3. Then lift the barre over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat banc. Your other foot should be stationary in front of you. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Conseil : Make sure votre dos is straight and poitrine is out while performing this exercise. 4. en inspirant, Lentement, lower your leg until your cuisses is parallel to le sol. At this point, your genoux should be over your toes. Your poitrine should be directly above the middle of your cuisses. 5. Leading with the poitrine and hips and contracting the quadriceps, elevate your leg back to the position de depart en expirant. 6. Repetez selon le nombre souhaite. 7. Switch legs and Repetez le mouvement.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Leg_Barbell_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Open Palm Kettlebell Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place one kettlebells between vos pieds. Clean the kettlebells by extending through the legs and hips as you raise the kettlebells towards your epaules. 2. Release the kettlebells as it comes up, and let it flip so that the ball of the kettlebells lands in the palms of vos mains. 3. Release the kettlebells out in front of you and catch the handle with both hands. Lower the kettlebells to the position de depart and Repetez.', 'Muscles secondaires : Fessiers, Bas du dos, Quadriceps, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Open_Palm_Kettlebell_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Otis-Up', 'Abdominaux', 'Autre', '1. Secure vos pieds and lay back on le sol. Your genoux should be bent. Hold a poids with both hands to your poitrine. Position de depart. 2. Initiate le mouvement by flexing the hips and spine to raise your torse up from the ground. 3. As you move up, press the poids up so that it is above your head at the top of le mouvement. 4. Return the poids to your poitrine as you reverse the sit-up motion, ensuring not to go all the way down to le sol.', 'Muscles secondaires : Pectoraux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Otis-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Cable Curl', 'Biceps', 'Poulie', '1. To begin, set a poids that is comfortable on each side of the pulley machine. Note: Make sure that the amount of poids selected is the same on each side. 2. Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your epaules. 3. Stand in the middle of both sides and use an prise en supination (palms facing towards the ceiling) to grab each handle. vos bras should be fully extended and parallel to le sol with vos pieds positioned epaules width apart from each other. votre corps should be evenly aligned the handles. Position de depart. 4. While exhaling, Lentement, squeeze the biceps on each side until your forearms and biceps touch. 5. While inhaling, move your forearms back to the position de depart. Note: Your entire body is stationary during this exercise except for the forearms. 6. Repetez selon le nombre souhaite. prescribed in your program.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Cable_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Lat', 'Dos', 'Autre', '1. Sit upright on le sol with your partner behind you. Raise one arm straight up, and flex the coudes, attempting to touch your hand to votre dos. Your parner should hold your triceps and poignets. Position de depart. 2. Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so. 3. After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the triceps. Hold for 10-20 seconds, and then switch sides.', 'Muscles secondaires : Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Lat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Slam', 'Dos', 'Medecine ball', '1. Hold a medine ball with both hands and Tenez-vous debout avec vos pieds at epaules width. Position de depart. 2. Initiate the countermovement by raising the ball above your head and fully extending votre corps. 3. Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can. 4. Receive the ball with both hands on the bounce and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Slam/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Squat', 'Quadriceps', 'Barre', '1. Start out by having a barre in front of you on le sol. vos pieds should be wider than epaules width apart from each other. 2. Bend the genoux and use a pronated grip (palms facing you) to grab the barre. vos mains should be at a wider than epaules width apart from each other before lifting. Once you are positioned, lift the barre up until you can rest it on your poitrine. 3. Move the barre over and slightly behind your head and make sure vos bras are fully extended. Keep your head up en permanence and also maintain a straight back. Retract your omoplates. Position de depart. 4. Lentement, lower the poids by bending your genoux until your cuisses are parallel to the ground while inhaling. Conseil : Keep votre dos straight while performing this exercise to avoid any injuries and vos bras should remain extended and over your head en permanence. 5. Now use vos pieds and legs to help bring the poids back up to the position de depart while exhaling. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Stretch', 'Abdominaux', 'Autre', '1. Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your epaules down as you extend vos bras up. 2. To create a full torse stretch, pull your tailbone down and stabilize your torse as you do this. Stretch the muscles on both the front and the back of the torse.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Triceps', 'Triceps', 'Poids de corps', '1. Sit upright on le sol with your partner behind you. Raise one arm straight up, and flex the coudes, attempting to touch your hand to votre dos. Your parner should hold your coudes and poignets. Position de depart. 2. Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so. 3. After 10-20 seconds, relax the arm and allow your partner to further stretch the triceps by applying gentle pressure to the poignets. Hold for 10-20 seconds, and then switch sides.', 'Muscles secondaires : Dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Triceps/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pallof Press', 'Abdominaux', 'Poulie', '1. Connect a standard handle to a tower, and—if possible—position the cable to epaules height. If not, a low pulley will suffice. 2. With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the poids on the cable. 3. With vos pieds positioned hip-width apart and genoux slightly bent, hold the cable to the middle of your poitrine. Position de depart. 4. Press the cable away from your poitrine, fully extending both arms. You sangle abdominale should be tight and engaged. 5. Hold the repetition for several seconds before returning to the position de depart. 6. At the conclusion of the set, Repetez facing the other direction.', 'Muscles secondaires : Pectoraux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pallof Press With Rotation', 'Abdominaux', 'Poulie', '1. Connect a standard handle to a tower, and position the cable to epaules height. 2. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the poids on the cable. Align outstretched arm with cable. 3. With vos pieds positioned hip-width apart, pull the cable into your poitrine and grab the handle with your other hand. Both hands should be on the handle at this time. 4. Facing forward, press the cable away from your poitrine. You sangle abdominale should be tight and engaged. 5. Keeping your hips straight, twist your torse away from the pulley until you get a full quarter rotation. 6. Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. vos bras should be extended in front of you. 7. With the side tension still engaging your sangle abdominale, bring vos mains to your poitrine and immediately press outward to a fully extended position. This constitutes one rep. 8. Repetez to failure. 9. Then, reposition and Repetez the same series of movements on the opposite side.', 'Muscles secondaires : Pectoraux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press_With_Rotation/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Palms-Down Dumbbell Wrist Curl Over A Bench', 'Avant-bras', 'Haltères', '1. Start out by placing two halteres on one side of a flat banc. 2. Kneel down on both of your genoux so that votre corps is facing the flat banc. 3. Use vos bras to grab both of the halteres with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat banc. Your poignets should be hanging over the edge. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. 6. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Palms-Down Wrist Curl Over A Bench', 'Avant-bras', 'Barre', '1. Start out by placing a barre on one side of a flat banc. 2. Kneel down on both of your genoux so that votre corps is facing the flat banc. 3. Use vos bras to grab the barre with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat banc. Your poignets should be hanging over the edge. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. 6. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Palms-Up Barbell Wrist Curl Over A Bench', 'Avant-bras', 'Barre', '1. Start out by placing a barre on one side of a flat banc. 2. Kneel down on both of your genoux so that votre corps is facing the flat banc. 3. Use vos bras to grab the barre with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat banc. Your poignets should be hanging over the edge. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. 6. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Palms-Up Dumbbell Wrist Curl Over A Bench', 'Avant-bras', 'Haltères', '1. Start out by placing two halteres on one side of a flat banc. 2. Kneel down on both of your genoux so that votre corps is facing the flat banc. 3. Use vos bras to grab both of the halteres with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat banc. Your poignets should be hanging over the edge. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. Make sure to inhale during this part of the exercise. 6. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Parallel Bar Dip', 'Triceps', 'Autre', '1. Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the position de depart with vos bras locked out. 2. Begin by flexing the coudes, lowering votre corps until vos bras break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. 3. Reverse the motion by extending the coudes, pushing yourself back up into the position de depart. 4. Repetez for the desired number of repetitions.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Parallel_Bar_Dip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pelvic Tilt Into Bridge', 'Bas du dos', 'Autre', '1. Lie down with vos pieds on le sol, heels directly under your genoux. 2. Lift only your tailbone to the ceiling to stretch your lower back. (Don''t lift the entire spine yet.) Pull in your stomach. 3. To go into a bridge, lift the entire spine except the neck.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pelvic_Tilt_Into_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Peroneals-SMR', 'Mollets', 'Foam roller', '1. Lay on your side, supporting your poids on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. Position de depart. 2. Raise your hips off of the ground and begin to roll from below the genoux to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repetez de l autre cote.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Peroneals-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Peroneals Stretch', 'Mollets', 'Autre', '1. In a seated position, loop a belt, rope, or band around one foot. Position de depart. 2. With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Peroneals_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Physioball Hip Bridge', 'Fessiers', 'Swiss ball', '1. Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on le sol, hip width apart or wider. Position de depart. 2. Begin by extending the hips using your fessiers and ischio-jambiers, raising your hips upward as you bridge. 3. Pause at the top of the motion and Revenez en position de depart.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Physioball_Hip_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pin Presses', 'Triceps', 'Barre', '1. Pin presses remove the eccentric phase of the banc press, developing starting strength. They also allow you to train a desired range of motion. 2. The banc should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your poitrine. The bar should be moved to the pins and prepared for lifting. 3. Begin by lying on the banc, with the bar directly above the contact point during your regular banc. Tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. 4. You can take a standard banc grip, or epaules width to focus on the triceps. The bar, poignets, and coudes should stay in line en permanence. Focus on squeezing the bar and trying to pull it apart. 5. Drive the bar up with as much force as possible. The coudes should be tucked in until lockout. 6. Return the bar to the pins, pausing before beginning the next repetition.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pin_Presses/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Piriformis-SMR', 'Fessiers', 'Foam roller', '1. Sit with your buttocks on top of a foam roll. Bend your genoux, and then cross one leg so that the ankle is over the genoux. Position de depart. 2. Shift your poids to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper fessiers. You may assist the stretch by using one hand to pull the bent genoux towards your poitrine. Hold this position for 10-30 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Piriformis-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plank', 'Abdominaux', 'Poids de corps', '1. Get into a prone position on le sol, supporting your poids on your toes and your forearms. vos bras are bent and directly below the epaules. 2. Keep votre corps straight en permanence, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plate Pinch', 'Avant-bras', 'Autre', '1. Grab two wide-rimmed plates and put them together with the smooth sides facing outward 2. Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. Position de depart. 3. Squeeze the plate with your fingers and thumb. Hold this position for as long as you can. 4. Repetez for the recommended amount of sets prescribed in your program. 5. Switch arms and Repetez le mouvements.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Pinch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plate Twist', 'Abdominaux', 'Autre', '1. Allongez-vous au sol or an exercise mat with vos jambes fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with vos bras slightly bent. 2. Lentement, cross vos jambes near your ankles and lift them up off the ground. Your genoux should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. Position de depart. 3. Move the plate to the left side and touch le sol with it. Expirez as you perform that movement. 4. Come back to the position de depart as you Inspirez and then Repetez le mouvement but this time to the right side of the body. Conseil : Use a slow controlled movement en permanence. Jerking motions can injure the back. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Twist/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Platform Hamstring Slides', 'Ischio-jambiers', 'Autre', '1. For this movement a wooden floor or similar is needed. Lay on votre dos with vos jambes extended. Place a gym towel or a light poids underneath your heel. Position de depart. 2. Begin le mouvement by flexing the genoux, keeping your other leg straight. 3. Continue bringing the heel closer to you, sliding it on le sol. 4. At full genoux flexion, reverse le mouvement to Revenez en position de depart.', 'Muscles secondaires : Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Platform_Hamstring_Slides/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plie Dumbbell Squat', 'Quadriceps', 'Haltères', '1. Hold a halteres at the base with both hands and stand straight up. Move vos jambes so that they are wider than epaules width apart from each other with your genoux slightly bent. 2. Your toes should be facing out. Note: vos bras should be stationary while performing the exercise. Position de depart. 3. Lentement, bend the genoux and lower vos jambes until your cuisses are parallel to le sol. Make sure to inhale as this is the eccentric part of the exercise. 4. Press mainly with the heel of the foot to bring the body back to the position de depart while exhaling. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plie_Dumbbell_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plyo Kettlebell Pushups', 'Pectoraux', 'Kettlebell', '1. Place a kettlebells on le sol. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebells, with your coudes extended. Position de depart. 2. Begin by lowering yourself as low as you can, keeping votre dos straight. 3. Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebells, switching hands as you do so. Continue le mouvement by descending and Repetezing le mouvement back and forth.', 'Muscles secondaires : Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plyo_Kettlebell_Pushups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plyo Push-up', 'Pectoraux', 'Poids de corps', '1. Move into a prone position on le sol, supporting your poids on vos mains and toes. 2. vos bras should be fully extended with the hands around epaules width. Keep votre corps straight throughout le mouvement. Position de depart. 3. Descend by flexing at the coudes, lowering your poitrine towards the ground. 4. At the bottom, reverse the motion by pushing yourself up through coudes extension as quickly as possible. Attempt to push your upper body up until vos mains leave the ground. 5. Revenez en position de depart and Repetez the exercise. 6. For added difficulty, add claps into le mouvement while you are air borne.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plyo_Push-up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Posterior Tibialis Stretch', 'Mollets', 'Autre', '1. In a seated position, loop a belt, rope, or band around one foot. Position de depart. 2. With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Posterior_Tibialis_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Clean', 'Ischio-jambiers', 'Barre', '1. Tenez-vous debout avec vos pieds slightly wider than epaules width apart and toes pointing out slightly. 2. Squat down and grasp bar with a closed, pronated grip. vos mains should be slightly wider than epaules width apart outside genoux with coudes fully extended. 3. Place the bar about 1 inch in front of your shins and over the balls of vos pieds. 4. votre dos should be flat or slightly arched, your poitrine held up and out and your omoplates should be retracted. 5. Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase. 6. Lift the bar from le sol by forcefully extending the hips and the genoux en expirant. Conseil : The upper torse should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the epaules (this would have the effect of pushing the fessiers in the air and stretching the ischio-jambiers. 7. Keep coudes fully extended with the head in a neutral position and the epaules over the bar. 8. As the bar raises keep it as close to the shins as possible. 9. As the bar passes the genoux, thrust your hips forward and slightly bend the genoux to avoid locking them. Conseil : At this point your cuisses should be against the bar. 10. Keep the back flat or slightly arched, coudes fully extended and your head neutral. Conseil : You will hold your breath until the next phase. 11. Inhale and then forcefully and quickly extend your hips and genoux and stand on your toes. 12. Keep the bar as close to votre corps as possible. Conseil : votre dos should be flat with the coudes pointed out to the sides and your head in a neutral position. Also, keep your epaules over the bar and arms straight as long as possible. 13. When your lower body joints are fully extended, shrug the epaules upward rapidly without letting the coudes flex yet. Exhale during this portion of le mouvement. 14. As the epaules reach their highest elevation flex your coudes to begin pulling votre corps under the bar. 15. Continue to pull the arms as high and as long as possible. Conseil : Due to the explosive nature of this phase, your torse will be erect or with an arched back, your head will be tilted back slightly and vos pieds may lose contact with le sol. 16. After the lower body has fully extended and the bar reaches near maximal height, pull votre corps under the bar and rotate the arms around and under the bar. 17. Simultaneously, flex the hips and genoux into a quarter squat position. 18. Once the arms are under the bar, inhale and then lift your coudes to position the upper arms parallel to le sol. Rack the bar across the front of your collar bones and front epaules muscles. 19. Catch the bar with an erect and tight torse, a neutral head position and flat feet. Exhale during this movement. 20. Stand up by extending the hips and genoux to a fully erect position. 21. Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the cuisses. Inhale during this movement. 22. Simultaneously flex the hips and genoux to cushion the impact of the bar on the cuisses. 23. Squat down with the coudes fully extended until the bar touches le sol. 24. Start over at Phase 1 and Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Bas du dos, Milieu du dos, Quadriceps, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Clean from Blocks', 'Ischio-jambiers', 'Barre', '1. With a barre on boxes of the desired height, take a grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight. As the bar approaches the mid-cuisses position, begin extending through the hips. 3. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the poids. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. 4. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the coudes up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the epaules, rotating your coudes under the bar as you do so. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. 5. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position, and complete the repetition by returning the poids to the boxes.', 'Muscles secondaires : Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Clean_from_Blocks/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Jerk', 'Quadriceps', 'Barre', '1. Standing with the poids racked on the front of the epaules, begin with the dip. With vos pieds directly under your hips, flex the genoux without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. 2. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the epaules. 3. At this moment as the feet leave le sol, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the genoux partially bent. 4. Receive the bar with the arms locked out overhead. 5. Return to a standing position.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Partials', 'Épaules', 'Haltères', '1. Tenez-vous debout avec your torse upright and a halteres on each hand being held bras tendus. The coudes should be close to the torse. 2. The palms of the hands should be facing your torse. vos pieds should be about epaules width apart. Position de depart. 3. Keeping vos bras straight and the torse stationary, lift the poids out to your sides until they are about epaules level height while exhaling. 4. Feel the contraction for a second and begin to lower the poids back down to the position de depart while inhaling. Conseil : Keep the palms facing down with the little finger slightly higher while lifting and lowering the poids as it will concentrate the stress on your epaules mainly. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Partials/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Snatch', 'Ischio-jambiers', 'Barre', '1. Begin with a loaded barre on le sol. The bar should be close to or touching the shins, and a prise large should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the poitrine up and the head looking forward. The epaules should be just in front of the bar. This will be the position de depart. 2. Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the genoux. 3. Transition into the second pull by extending through the hips genoux and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the epaules and allow the coudes to flex to the side. 4. As you move vos pieds into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead. 5. Return to a standing position with the poids over head.', 'Muscles secondaires : Mollets, Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Snatch from Blocks', 'Quadriceps', 'Barre', '1. Begin with a loaded barre on boxes or stands of the desired height. A prise large should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the poitrine up and the head looking forward. The epaules should be just in front of the bar, with the coudes pointed out. This will be the position de depart. 2. Begin the first pull by driving through the front of the heels, raising the bar from the boxes. 3. Transition into the second pull by extending through the hips genoux and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the epaules and allow the coudes to flex to the side. 4. As you move vos pieds into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead. 5. Keeping the bar aligned over the front of the heels, your head and poitrine up, drive through heels of the feet to move to a standing position. Carefully return the poids to the boxes.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch_from_Blocks/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Stairs', 'Ischio-jambiers', 'Autre', '1. In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box. 2. Begin by taking the implement with both hands. Set vos pieds wide, with your head and poitrine up. Drive through the ground with your heels, extending your genoux and hips to raise the poids from the ground. 3. As you lean back, attempt to swing the poids onto the stairs, which are usually around 16-18" high. You can use vos jambes to help push the poids onto the stair. 4. Repetez for 3-5 repetitions, and continue with a heavier poids, moving as fast as possible.', 'Muscles secondaires : Adducteurs, Mollets, Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Stairs/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Preacher Curl', 'Biceps', 'Barre', '1. To perform this movement you will need a preacher banc and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of vos mains should be facing forward and they should be slightly tilted inwards due to the shape of the bar. 2. With the upper arms positioned against the preacher banc pad and the poitrine against it, hold the E-Z Curl Bar at epaules length. Position de depart. 3. As you Inspirez, Lentement, lower the bar until your upper arm is extended and the biceps is fully stretched. 4. en expirant, use the biceps to curl the poids up until your biceps is entierement contracte and the bar is at epaules height. Squeeze the biceps hard and hold this position for a second. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Preacher Hammer Dumbbell Curl', 'Biceps', 'Haltères', '1. Place the upper part of both arms on top of the preacher banc as you hold a halteres in each hand with the palms facing each other (neutral grip). 2. As you Inspirez, Lentement, lower the halteres until your upper arm is extended and the biceps is fully stretched. 3. en expirant, use the biceps to curl the poids up until your biceps is entierement contracte and the halteres are at epaules height. 4. Squeeze the biceps hard for a second at the contracted position and Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Hammer_Dumbbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Press Sit-Up', 'Abdominaux', 'Barre', '1. To begin, lie down on a banc with a barre resting on your poitrine. Position vos jambes so they are secure on the extension of the abdominal banc. Position de depart. 2. While inhaling, tighten your abdominals and fessiers. Simultaneously curl your torse as you do when performing a sit-up and press the barre to an overhead position while exhaling. Conseil : Use vos bras to push the barre out as you perform this exercise while still focusing on the abdominal muscles. 3. Lower your upper body back down to the position de depart while bringing the barre back down to your torse. Remember to Inspirez while lowering the body. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Press_Sit-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Prone Manual Hamstring', 'Ischio-jambiers', 'Autre', '1. You will need a partner for this exercise. Lay face down with vos jambes straight. Your assistant will place their hand on your heel. 2. To begin, flex the genoux to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as le mouvement is completed. Communicate with your partner to monitor appropriate resistance levels. 3. Pause at the top, returning the leg to the position de depart as your partner provides resistance going the other direction.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Prone_Manual_Hamstring/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Prowler Sprint', 'Ischio-jambiers', 'Autre', '1. Place your sled on an appropriate surface, loaded to a suitable poids. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down. 2. You may use the upright or the low handles for this exercise. Place vos mains on the handles with vos bras extended, leaning into the implement. 3. With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.', 'Muscles secondaires : Mollets, Pectoraux, Fessiers, Quadriceps, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Prowler_Sprint/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pull Through', 'Fessiers', 'Poulie', '1. Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with vos pieds set wide apart. 2. Begin le mouvement by reaching through vos jambes as far as possible, bending at the hips. Keep your genoux slightly bent. Keeping vos bras straight, extend through the hip to stand straight up. Avoid pulling upward through the epaules; all of the motion should originate through the hips.', 'Muscles secondaires : Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pullups', 'Dos', 'Poids de corps', '1. Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a prise large, vos mains need to be spaced out at a distance wider than your epaules width. For a prise moyenne, vos mains need to be spaced out at a distance equal to your epaules width and for a close grip at a distance smaller than your epaules width. 2. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart. 3. Pull your torse up until the bar touches your upper poitrine by drawing the epaules and the upper arms down and back. Exhale as you perform this portion of le mouvement. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar. 4. After a second on the contracted position, start to inhale and Lentement, lower your torse back to the position de depart when vos bras are fully extended and the lats are fully stretched. 5. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push-Up Wide', 'Pectoraux', 'Poids de corps', '1. With vos mains wide apart, support votre corps on your toes and hands in a plank position. Your coudes should be extended and votre corps straight. Do not allow your hips to sag. Position de depart. 2. To begin, allow the coudes to flex, lowering your poitrine to le sol en inspirant. 3. Using your pectoral muscles, press your upper body back up to the position de depart by extending the coudes. Exhale as you perform this step. 4. After pausing at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Up_Wide/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push-Ups - Close Triceps Position', 'Triceps', 'Poids de corps', '1. Allongez-vous au sol face down and place vos mains closer than epaules width for a close hand position. Make sure that you are holding your torse up at arms'' length. 2. Lower yourself until your poitrine almost touches le sol en inspirant. 3. Using your triceps and some of your pectoral muscles, press your upper body back up to the position de depart and squeeze your poitrine. Expirez as you perform this step. 4. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_-_Close_Triceps_Position/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push-Ups With Feet Elevated', 'Pectoraux', 'Poids de corps', '1. Allongez-vous au sol face down and place vos mains about 36 inches apart from each other holding your torse up bras tendus. 2. Place your toes on top of a flat banc. This will allow votre corps to be elevated. Note: The higher the elevation of the flat banc, the higher the resistance of the exercise is. 3. Lower yourself until your poitrine almost touches le sol en inspirant. 4. Using your pectoral muscles, press your upper body back up to the position de depart and squeeze your poitrine. Expirez as you perform this step. 5. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_With_Feet_Elevated/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push-Ups With Feet On An Exercise Ball', 'Pectoraux', 'Swiss ball', '1. Allongez-vous au sol face down and place vos mains about 36 inches apart from each other holding your torse up bras tendus. 2. Place your toes on top of an exercise ball. This will allow votre corps to be elevated. 3. Lower yourself until your poitrine almost touches le sol en inspirant. 4. Using your pectoral muscles, press your upper body back up to the position de depart and squeeze your poitrine. Expirez as you perform this step. 5. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push Press', 'Épaules', 'Barre', '', 'Muscles secondaires : Quadriceps, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push Press - Behind the Neck', 'Épaules', 'Barre', '1. Standing with the poids racked on the back of the epaules, begin with the dip. With vos pieds directly under your hips, flex the genoux without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path. 2. Using the momentum generated, finish pressing the poids overhead be extending through the arms. 3. Revenez en position de depart, using vos jambes to absorb the impact.', 'Muscles secondaires : Mollets, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Press_-_Behind_the_Neck/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push Up to Side Plank', 'Pectoraux', 'Poids de corps', '1. Get into pushup position on the toes with vos mains just outside of epaules width. 2. Perform a pushup by allowing the coudes to flex. As you descend, keep votre corps straight. 3. Do one pushup and as you come up, shift your poids on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank. 4. Lower the arm back to le sol for another pushup and then twist to the other side. 5. Repetez the series, alternating each side, for 10 or more reps.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Up_to_Side_Plank/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pushups', 'Pectoraux', 'Poids de corps', '1. Allongez-vous au sol face down and place vos mains about 36 inches apart while holding your torse up bras tendus. 2. Next, lower yourself downward until your poitrine almost touches le sol en inspirant. 3. Now Expirez and press your upper body back up to the position de depart while squeezing your poitrine. 4. Apres une pause, at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pushups (Close and Wide Hand Positions)', 'Pectoraux', 'Poids de corps', '1. Allongez-vous au sol face down and body straight with your toes on le sol and the hands wider than epaules width for a wide hand position and closer than epaules width for a close hand position. Make sure you are holding your torse up bras tendus. 2. Lower yourself until your poitrine almost touches le sol en inspirant. 3. Using your pectoral muscles, press your upper body back up to the position de depart and squeeze your poitrine. Expirez as you perform this step. 4. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups_Close_and_Wide_Hand_Positions/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pyramid', 'Bas du dos', 'Swiss ball', '1. Start off by rolling your torse forward onto the ball so your hips rest on top of the ball and become the highest point of votre corps. 2. Rest vos mains and feet on le sol. vos bras and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torse and epaules.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pyramid/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Quad Stretch', 'Quadriceps', 'Autre', '1. Lay on your side. Loop a belt, rope, or band around your top foot. Flex the genoux and extend your hip, attempting to touch your fessiers with your foot, and holding the belt with vos mains. Position de depart. 2. With the belt being held over the epaules or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Quadriceps-SMR', 'Quadriceps', 'Foam roller', '1. Lay facedown on le sol with your poids supported by vos mains or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. Position de depart. 2. Shifting as much poids onto the leg to be stretched as is tolerable, roll over the foam from above the genoux to below the hip, holding points of tension for 10-30 seconds. Switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quadriceps-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Quick Leap', 'Quadriceps', 'Autre', '1. You will need a box for this exerise. 2. Begin facing the box standing 1-2 feet from its edge. 3. By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with vos jambes bent and vos pieds flat. 4. Immediately upon landing, fully extend through the entire body and swing vos bras overhead to explode off of the box. Use vos jambes to absorb the impact of landing.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quick_Leap/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rack Delivery', 'Épaules', 'Barre', '1. This drill teaches the delivery of the barre to the rack position on the epaules. Begin holding a bar in the scarecrow position, with the upper arms parallel to le sol, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs. 2. Begin by rotating the coudes around the bar, delivering the bar to the epaules. As your coudes come forward, relax your grip. The epaules should be protracted, providing a shelf for the bar, which should lightly contact the throat. 3. It is important that the bar stay close to the body en permanence, as with a heavier load any distance will result in an unwanted collision. As le mouvement becomes smoother, speed and load can be increased before progressing further.', 'Muscles secondaires : Avant-bras, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Delivery/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rack Pull with Bands', 'Bas du dos', 'Barre', '1. Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the genoux, just above, or in the mid cuisses position. Attach bands to the base of the rack, or secure them with halteres. Attach the other end to the bar. You may need to choke the bands to provide tension. 2. Position yourself against the bar in proper deadlifting position. vos pieds should be under your hips, your grip epaules width, back arched, and hips back to engage the ischio-jambiers. Since the poids is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the poids. 3. With your head looking forward, extend through the hips and genoux, pulling the poids up and back until lockout. Be sure to pull your epaules back as you complete le mouvement. Return the poids to the pins and Repetez.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pull_with_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rack Pulls', 'Bas du dos', 'Barre', '1. Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the genoux, just above, or in the mid cuisses position. Position yourself against the bar in proper deadlifting position. vos pieds should be under your hips, your grip epaules width, back arched, and hips back to engage the ischio-jambiers. Since the poids is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the poids. 2. With your head looking forward, extend through the hips and genoux, pulling the poids up and back until lockout. Be sure to pull your epaules back as you complete le mouvement. 3. Return the poids to the pins and Repetez.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pulls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rear Leg Raises', 'Quadriceps', 'Poids de corps', '1. Place yourself on vos mains genoux on an exercise mat. Your head should be looking forward and the bend of the genoux should create a 90-degree angle between the ischio-jambiers and the mollets. Position de depart. 2. Extend one leg up and behind you. The genoux and hip should both extend. Repetez for 5-10 repetitions, and then switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rear_Leg_Raises/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Recumbent Bike', 'Quadriceps', 'Machine', '1. To begin, seat yourself on the bike and adjust the seat to your height. 2. Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity. 3. Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Recumbent_Bike/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Return Push from Stance', 'Épaules', 'Medecine ball', '1. You will need a partner for this drill. 2. Begin in an athletic 2 or 3 point stance. 3. At the signal, move into a position to receive the pass from your partner. 4. Catch the medicine ball with both hands and immediately throw it back to your partner. 5. You can modify this drill by running different routes.', 'Muscles secondaires : Pectoraux, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Return_Push_from_Stance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Bench Press', 'Triceps', 'Barre', '1. Position a banc inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barre. 2. Lie on the banc, tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. However wide your grip, it should cover the ring on the bar. 3. Pull the bar out of the rack without protracting your epaules. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower poitrine or upper stomach. The bar, poignets, and coudes should stay in line en permanence. 4. Pause when the barre touches your torse, and then drive the bar up with as much force as possible. The coudes should be tucked in until lockout.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Box Squat', 'Quadriceps', 'Barre', '1. Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wider for more emphasis on the back, fessiers, adductors, and ischio-jambiers, or closer together for more quad development. Keep your head facing forward. 3. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward off of the box as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barre to the rack.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Box_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Deadlift', 'Bas du dos', 'Barre', '1. Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar. 2. Approach the bar so that it is centered over vos pieds. You feet should be about hip width apart. Bend at the hip to grip the bar at epaules width, allowing your omoplates to protract. Typically, you would use an prise en pronation or an over/under grip on heavier sets. 3. With vos pieds, and your grip set, take a big breath and then lower your hips and bend the genoux until your shins contact the bar. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. 4. After the bar passes the genoux, aggressively pull the bar back, pulling your omoplates together as you drive your hips forward into the bar. 5. Lower the bar by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Power Squat', 'Quadriceps', 'Barre', '1. Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wide for more emphasis on the back, fessiers, adductors, and ischio-jambiers. 3. Keep your head facing forward. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torse lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the genoux. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the position de depart.', 'Muscles secondaires : Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Power_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Sumo Deadlift', 'Ischio-jambiers', 'Barre', '1. Begin with a bar loaded on le sol inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barre. 2. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the epaules, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the epaules, which in effect lengthens vos bras. 3. Take a breath, and then lower your hips, looking forward with your head with your poitrine up. Drive through le sol, spreading vos pieds apart, with your poids on the back half of vos pieds. Extend through the hips and genoux. 4. As the bar passes through the genoux, lean back and drive the hips into the bar, pulling your omoplates together. 5. Return the poids to the ground by bending at the hips and controlling the poids on the way down.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Avant-bras, Fessiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Sumo_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Barbell Curl', 'Biceps', 'Barre', '1. Tenez-vous debout avec your torse upright while holding a barre at epaules width with the coudes close to the torse. The palm of vos mains should be facing down (pronated grip). Position de depart. 2. While holding the upper arms stationary, curl the poids while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde as you squeeze the muscle. 3. Lentement, begin to bring the bar back to position de depart as your Inspirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Barbell Preacher Curls', 'Biceps', 'Barre EZ', '1. Grab an EZ-bar using a epaules width and palms down (pronated) grip. 2. Now place the upper part of both arms on top of the preacher banc and have vos bras extended. Position de depart. 3. en expirant, use the biceps to curl the poids up until your biceps are entierement contracte and the barre is at epaules height. Squeeze the biceps hard for a second at the contracted position. 4. As you Inspirez, Lentement, lower the barre until your upper arms are extended and the biceps is fully stretched. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Barbell_Preacher_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Cable Curl', 'Biceps', 'Poulie', '1. Tenez-vous debout avec your torse upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and epaules width grip. Make sure also that you keep the coudes close to the torse. Position de depart. 2. While holding the upper arms stationary, curl the poids while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde as you squeeze the muscle. 3. Lentement, begin to bring the bar back to position de depart as your Inspirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Cable_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Crunch', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with vos jambes fully extended and arms to the side of your torse with the palms on le sol. vos bras should be stationary for the entire exercise. 2. Move vos jambes up so that your cuisses are perpendicular to le sol and feet are together and parallel to le sol. Position de depart. 3. While inhaling, move vos jambes towards the torse as you roll your pelvis backwards and you raise your hips off le sol. At the end of this movement your genoux will be touching your poitrine. 4. Hold the contraction for a second and move vos jambes back to the position de depart while exhaling. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Flyes', 'Épaules', 'Haltères', '1. To begin, lie down on an incline banc with the poitrine and stomach pressing against the incline. Have the halteres in each hand with the palms facing each other (neutral grip). 2. Extend the arms in front of you so that they are perpendicular to the angle of the banc. The legs should be stationary while applying pressure with the ball of your toes. Position de depart. 3. Maintaining the slight bend of the coudes, move the poids out and away from each other (to the side) in an arc motion while exhaling. Conseil : Try to squeeze your omoplates together to get the best results from this exercise. 4. The arms should be elevated until they are parallel to le sol. 5. Feel the contraction and Lentement, lower the poids back down to the position de depart while inhaling. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Flyes With External Rotation', 'Épaules', 'Haltères', '1. To begin, lie down on an incline banc set at a 30-degree angle with the poitrine and stomach pressing against the incline. 2. Have the halteres in each hand with the palms facing down to le sol. vos bras should be in front of you so that they are perpendicular to the angle of the banc. Conseil : Your coudes should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching le sol). Position de depart. 3. Maintaining the slight bend of the coudes, move the poids out and away from each other in an arc motion while exhaling. 4. As you lift the poids, your poignets should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Conseil : Try to squeeze your omoplates together to get the best results from this exercise. 5. The arms should be elevated until they are level with the head. 6. Feel the contraction and Lentement, lower the poids back down to the position de depart while inhaling. 7. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Flyes_With_External_Rotation/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Grip Bent-Over Rows', 'Milieu du dos', 'Barre', '1. Stand erect while holding a barre with a supinated grip (palms facing up). 2. Bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Conseil : Make sure that you keep the head up. The barre should hang directly in front of you as vos bras hang perpendicular to le sol and your torse. Position de depart. 3. While keeping the torse stationary, lift the barre as you Expirez, keeping the coudes close to the body and not doing any force with the forearm other than holding the poids. On the top contracted position, squeeze the back muscles and Maintenez 1 seconde. 4. Lentement, lower the poids again to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Bent-Over_Rows/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Grip Triceps Pushdown', 'Triceps', 'Poulie', '1. Start by setting a bar attachment (straight or e-z) on a high pulley machine. 2. Facing the bar attachment, grab it with the palms facing up (supinated grip) at epaules width. Lower the bar by using your lats until vos bras are fully extended by your sides. Conseil : coudes should be in by your sides and vos pieds should be epaules width apart from each other. Position de depart. 3. Lentement, elevate the bar attachment up en inspirant so it is aligned with your poitrine. Only the forearms should move and the coudes/upper arms should be stationary by your side en permanence. 4. Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Triceps_Pushdown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Hyperextension', 'Ischio-jambiers', 'Machine', '1. Place vos pieds between the pads after loading an appropriate poids. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position. 2. To begin le mouvement, flex the hips, pulling the legs forward. 3. Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion. 4. Return by again flexing the hip, pulling the carriage forward as far as you can. 5. Repetez for the desired number of repetitions.', 'Muscles secondaires : Mollets, Fessiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Hyperextension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Machine Flyes', 'Épaules', 'Machine', '1. Adjust the handles so that they are fully to the rear. Make an appropriate poids selection and adjust the seat height so the handles are at epaules level. Grasp the handles with vos mains facing inwards. Position de depart. 2. In a semicircular motion, pull vos mains out to your side and back, contracting your rear delts. 3. Keep vos bras slightly bent throughout le mouvement, with all of the motion occurring at the epaules joint. 4. Pause at the rear of le mouvement, and Lentement, return the poids to the position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Machine_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Plate Curls', 'Biceps', 'Autre', '1. Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position. 2. vos pieds should be epaules width apart from each other and the weighted plate should be near the groin area. Position de depart. 3. Lentement, lift the plate up while keeping the coudes in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torse at this point. 4. Feel the contraction for a second and begin to lower the poids back down to the position de depart while inhaling 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Plate_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Triceps Bench Press', 'Triceps', 'Barre', '1. Allongez-vous au sol on a flat banc. Using a close, supinated grip (around epaules width), lift the bar from the rack and hold it straight over you with vos bras locked extended in front of you and perpendicular to le sol. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your middle poitrine. Conseil : Make sure that as opposed to a regular banc press, you keep the coudes close to the torse en permanence in order to maximize triceps involvement. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your triceps muscles. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Triceps_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rhomboids-SMR', 'Milieu du dos', 'Foam roller', '1. Lay down with votre dos on le sol. Place a foam roll underneath your upper back, and cross vos bras in front of you, protracting your epaules. Position de depart. 2. Raise your hips off of the ground, placing your poids onto the foam roll. Shift your poids to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds.', 'Muscles secondaires : Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rhomboids-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rickshaw Carry', 'Avant-bras', 'Autre', '1. Position the frame at the starting point, and load with the appropriate poids. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your poitrine and head are up and votre dos is straight. 2. Immediately begin walking briskly with quick, controlled steps. Keep your poitrine up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rickshaw_Carry/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rickshaw Deadlift', 'Quadriceps', 'Autre', '1. Load the frame with the desired poids. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your omoplates to protract. 2. With vos pieds and your grip set, take a big breath and then lower your hips and flex the genoux. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. As the poids comes up, pull your omoplates together as you drive your hips forward. 3. Lower the poids by bending at the hips and guiding it to the ground.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rickshaw_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
